#pragma once
#include "rinkfit/joint_packet.hpp"
#include <sstream>
namespace rinkfit {
inline std::string joint_path_RLE(const std::vector<std::uint32_t>&paths){std::string out;out.reserve(paths.size());for(std::size_t i=0;i<paths.size();){std::size_t j=i+1;while(j<paths.size()&&paths[j]==paths[i])++j;out+=std::to_string(j-i)+":"+std::to_string(paths[i])+";";i=j;}return out;}
inline std::string joint_path_RLE(const JointPacket&p){std::vector<std::uint32_t>v;v.reserve(p.rows.size());for(const auto&r:p.rows)v.push_back(std::uint32_t(r.path));return joint_path_RLE(v);}
inline void restore_joint_path_RLE(const std::string&encoded,JointPacket&p,const JointEventModel&m){std::size_t offset=0,position=0;while(position<encoded.size()){auto colon=encoded.find(':',position),end=encoded.find(';',position);if(colon==std::string::npos||end==std::string::npos||colon>=end)throw std::runtime_error("invalid checkpoint material path RLE");std::size_t used=0;auto count=std::stoull(encoded.substr(position,colon-position),&used);if(!count||used!=colon-position||count>p.rows.size()-offset)throw std::runtime_error("invalid checkpoint material path run count");auto value=std::stoull(encoded.substr(colon+1,end-colon-1),&used);if(used!=end-colon-1)throw std::runtime_error("invalid checkpoint path value");for(std::size_t i=0;i<count;++i){auto&r=p.rows[offset++];if(r.active&&(value>=m.materials.at(r.material).paths.size()||(r.kind==1&&!m.materials.at(r.material).paths[value].physical_point)))throw std::runtime_error("checkpoint finite material/entity path identity invalid");r.path=int(value);}position=end+1;}if(offset!=p.rows.size())throw std::runtime_error("incomplete checkpoint material path table");}
}
